-- ============================================================================================================
-- RASCUNHO · NÃO É MIGRATION FLYWAY. Proposta de taxonomia de peças (docs/taxonomia/AUDITORIA_TAXONOMIA_PECAS.md, seção E/G).
-- Gerado a partir de docs/taxonomia/proposta/taxonomia_variacoes.json. MySQL 8.0+/9.x, InnoDB, utf8mb4.
-- Categorias/subcategorias reaproveitam os códigos existentes (lower_snake_case) como chave natural: wardrobe_items.subcategory
-- e catalog_products.subcategory já guardam exatamente esses códigos, então nada é renomeado.
-- Na migration real (V39+): mesmas tabelas, sem DROP; o bloco final (colunas em wardrobe_items/catalog_products) entra em V40+.
-- ============================================================================================================
SET NAMES utf8mb4;

CREATE TABLE piece_category (
  code VARCHAR(40) NOT NULL PRIMARY KEY,
  display_name_pt VARCHAR(80) NOT NULL,
  display_name_en VARCHAR(80) NOT NULL,
  sort_order SMALLINT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE piece_subcategory (
  code VARCHAR(60) NOT NULL PRIMARY KEY,
  category_code VARCHAR(40) NOT NULL,
  display_name_pt VARCHAR(80) NOT NULL,
  display_name_en VARCHAR(80) NOT NULL,
  sort_order SMALLINT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',             -- ACTIVE | DEPRECATED (nunca apagar: há peças apontando)
  concept_issue VARCHAR(30) NULL,                           -- LENGTH, SHAFT_HEIGHT, USAGE_TYPE, MATERIAL… (auditoria)
  implied_attributes_json JSON NULL,                        -- ex.: {"SHAFT_HEIGHT":"HIGH_TOP"} para high_top_sneakers
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_piece_subcategory_category FOREIGN KEY (category_code) REFERENCES piece_category(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE piece_variation (
  code VARCHAR(60) NOT NULL PRIMARY KEY,
  display_name_pt VARCHAR(80) NOT NULL,
  display_name_en VARCHAR(80) NOT NULL,
  description_pt VARCHAR(255) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- N:N — a mesma variação (STRAIGHT, MULE, COWBOY…) vale em várias subcategorias; tier/prioridade são do vínculo.
CREATE TABLE piece_subcategory_variation (
  subcategory_code VARCHAR(60) NOT NULL,
  variation_code VARCHAR(60) NOT NULL,
  tier VARCHAR(10) NOT NULL,                                -- CORE | EXTENDED | NICHE
  priority TINYINT NOT NULL,                                -- 1 (mais importante) … 5
  sort_order SMALLINT NOT NULL,
  implied_attributes_json JSON NULL,                        -- padrão editável (ex.: CHELSEA → {"CLOSURE":"SLIP_ON"})
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (subcategory_code, variation_code),
  KEY idx_psv_variation (variation_code),
  CONSTRAINT fk_psv_subcategory FOREIGN KEY (subcategory_code) REFERENCES piece_subcategory(code),
  CONSTRAINT fk_psv_variation FOREIGN KEY (variation_code) REFERENCES piece_variation(code),
  CONSTRAINT ck_psv_tier CHECK (tier IN ('CORE','EXTENDED','NICHE')),
  CONSTRAINT ck_psv_priority CHECK (priority BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Aliases (PT/EN/grafias de varejo) para IA, busca e NLP. scope_subcategory = '*' vale onde a variação se aplica;
-- um código de subcategoria restringe o alias àquela subcategoria (ex.: 'pantalona' → WIDE_LEG só em jeans).
CREATE TABLE piece_variation_alias (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  variation_code VARCHAR(60) NOT NULL,
  scope_subcategory VARCHAR(60) NOT NULL DEFAULT '*',
  alias VARCHAR(120) NOT NULL,
  alias_norm VARCHAR(120) NOT NULL,                         -- CatalogNormalizer.key(alias)
  CONSTRAINT uq_pva UNIQUE (variation_code, scope_subcategory, alias_norm),
  KEY idx_pva_norm (alias_norm),
  CONSTRAINT fk_pva_variation FOREIGN KEY (variation_code) REFERENCES piece_variation(code) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE attribute_dimension (
  code VARCHAR(40) NOT NULL PRIMARY KEY,
  display_name_pt VARCHAR(80) NOT NULL,
  display_name_en VARCHAR(80) NOT NULL,
  cardinality VARCHAR(10) NOT NULL,                         -- SINGLE | MULTI
  max_values TINYINT NOT NULL,                              -- peça
  max_values_scheme TINYINT NULL,                           -- esquema (STYLE/OCCASION = 3)
  scope VARCHAR(20) NOT NULL,                               -- PIECE | CATALOG | PIECE_AND_SCHEME
  source VARCHAR(10) NOT NULL,                              -- EXISTING | NEW
  derived BOOLEAN NOT NULL DEFAULT FALSE,                   -- PRICE_RANGE: calculada, nunca digitada
  sort_order SMALLINT NOT NULL,
  note VARCHAR(512) NULL,
  CONSTRAINT ck_ad_card CHECK (cardinality IN ('SINGLE','MULTI'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE attribute_value (
  dimension_code VARCHAR(40) NOT NULL,
  code VARCHAR(60) NOT NULL,                                -- códigos existentes preservados (cores/estilos/ocasiões lower_snake)
  display_name_pt VARCHAR(80) NOT NULL,
  display_name_en VARCHAR(80) NOT NULL,
  tier VARCHAR(10) NOT NULL DEFAULT 'CORE',
  parent_code VARCHAR(60) NULL,                             -- MATERIAL_DETAIL → família MATERIAL; COLOR → família
  hex CHAR(7) NULL,
  min_brl DECIMAL(10,2) NULL,
  max_brl DECIMAL(10,2) NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',             -- ACTIVE | PROPOSED | DEPRECATED
  sort_order SMALLINT NOT NULL,
  PRIMARY KEY (dimension_code, code),
  CONSTRAINT fk_av_dimension FOREIGN KEY (dimension_code) REFERENCES attribute_dimension(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE attribute_value_alias (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  dimension_code VARCHAR(40) NOT NULL,
  value_code VARCHAR(60) NOT NULL,
  alias VARCHAR(120) NOT NULL,
  alias_norm VARCHAR(120) NOT NULL,
  CONSTRAINT uq_ava UNIQUE (dimension_code, value_code, alias_norm),
  KEY idx_ava_norm (dimension_code, alias_norm),
  CONSTRAINT fk_ava_value FOREIGN KEY (dimension_code, value_code) REFERENCES attribute_value(dimension_code, code) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- appliesTo materializado por subcategoria: value_code '*' = a dimensão inteira; um código = só aquele valor.
CREATE TABLE attribute_applicability (
  dimension_code VARCHAR(40) NOT NULL,
  value_code VARCHAR(60) NOT NULL DEFAULT '*',
  subcategory_code VARCHAR(60) NOT NULL,
  PRIMARY KEY (dimension_code, value_code, subcategory_code),
  KEY idx_aa_sub (subcategory_code, dimension_code),
  CONSTRAINT fk_aa_dimension FOREIGN KEY (dimension_code) REFERENCES attribute_dimension(code),
  CONSTRAINT fk_aa_subcategory FOREIGN KEY (subcategory_code) REFERENCES piece_subcategory(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Atribuições por item (EAV tipado e indexado para facetas com contagem). Sem FK para wardrobe_items/catalog_products
-- neste rascunho (o schema descartável não tem essas tabelas); na migration real as FKs entram (ON DELETE CASCADE).
CREATE TABLE catalog_product_attribute (
  product_id CHAR(36) NOT NULL,
  dimension_code VARCHAR(40) NOT NULL,
  value_code VARCHAR(60) NOT NULL,
  source VARCHAR(20) NOT NULL,                              -- OFFICIAL | RULE | ALIAS | AI | USER | ADMIN
  confidence DECIMAL(4,3) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (product_id, dimension_code, value_code),
  KEY idx_cpa_facet (dimension_code, value_code, product_id),
  CONSTRAINT fk_cpa_value FOREIGN KEY (dimension_code, value_code) REFERENCES attribute_value(dimension_code, code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE wardrobe_item_attribute (
  item_id CHAR(36) NOT NULL,
  dimension_code VARCHAR(40) NOT NULL,
  value_code VARCHAR(60) NOT NULL,
  source VARCHAR(20) NOT NULL,                              -- CATALOG | AI | USER | RULE
  confidence DECIMAL(4,3) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (item_id, dimension_code, value_code),
  KEY idx_wia_facet (dimension_code, value_code, item_id),
  CONSTRAINT fk_wia_value FOREIGN KEY (dimension_code, value_code) REFERENCES attribute_value(dimension_code, code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


