-- ───────────── dimensões de atributo

INSERT INTO attribute_dimension (code, display_name_pt, display_name_en, cardinality, max_values, max_values_scheme, scope, source, derived, sort_order, note) VALUES
  ('COLOR', 'Cor', 'Color', 'SINGLE', 1, NULL, 'PIECE', 'EXISTING', 0, 1, 'Paleta de Taxonomy.java (59 códigos, com família e hex). ''print'' e ''multicolor'' misturam estampa com cor — manter por compatibilidade, preferir PATTERN.'),
  ('MATERIAL', 'Material (família)', 'Material family', 'SINGLE', 1, NULL, 'PIECE', 'EXISTING', 0, 2, '7 famílias existentes (obrigatórias no formulário). LINEN, VISCOSE e METAL são PROPOSTAS aditivas.'),
  ('MATERIAL_DETAIL', 'Tecido / matéria-prima', 'Fabric / raw material', 'MULTI', 3, NULL, 'PIECE', 'NEW', 0, 3, 'Cada valor aponta para a família (MATERIAL). Preenche MATERIAL automaticamente quando ele estiver vazio.'),
  ('PATTERN', 'Estampa', 'Pattern', 'SINGLE', 1, NULL, 'PIECE', 'EXISTING', 0, 4, 'Reaproveita normalization.json → design.patterns (sem renomear). Valores novos marcados PROPOSED.'),
  ('LOGO_PLACEMENT', 'Posição do logo', 'Logo placement', 'SINGLE', 1, NULL, 'PIECE', 'EXISTING', 0, 5, NULL),
  ('STYLE', 'Estilo', 'Style', 'MULTI', 2, 3, 'PIECE_AND_SCHEME', 'EXISTING', 0, 6, 'Taxonomy.STYLES (25). Peça ≤ 2 (MAX_PIECE_TAGS), esquema ≤ 3 (MAX_SCHEME_TAGS).'),
  ('OCCASION', 'Ocasião', 'Occasion', 'MULTI', 2, 3, 'PIECE_AND_SCHEME', 'EXISTING', 0, 7, 'Taxonomy.OCCASIONS (20), restritas por categoria via WEARSTYLES_BY_PART (allowedOccasionsByCategory).'),
  ('GENDER', 'Gênero', 'Gender', 'SINGLE', 1, NULL, 'PIECE', 'EXISTING', 0, 8, NULL),
  ('PRICE_RANGE', 'Faixa de preço', 'Price range', 'SINGLE', 1, NULL, 'CATALOG', 'NEW', 1, 9, 'Derivada de price_amount (BRL) — nunca digitada. Limites a validar com o fundador.'),
  ('FIT', 'Caimento', 'Fit', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 10, 'Folga do tronco. Em partes de baixo o caimento da perna JÁ é a variação (jeans SLIM, RELAXED…), por isso FIT não se aplica a elas.'),
  ('WAIST_RISE', 'Cintura (altura)', 'Rise', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 11, NULL),
  ('LENGTH', 'Comprimento', 'Length', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 12, 'Cada valor declara a que subcategorias se aplica; o select mostra só os valores válidos para a subcategoria escolhida.'),
  ('SLEEVE_LENGTH', 'Manga (comprimento)', 'Sleeve length', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 13, NULL),
  ('SLEEVE_STYLE', 'Manga (modelo)', 'Sleeve style', 'MULTI', 2, NULL, 'PIECE', 'NEW', 0, 14, NULL),
  ('NECKLINE', 'Decote / gola', 'Neckline / collar', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 15, NULL),
  ('CLOSURE', 'Fechamento', 'Closure', 'MULTI', 2, NULL, 'PIECE', 'NEW', 0, 16, NULL),
  ('FINISH', 'Acabamento / lavagem', 'Finish / wash', 'MULTI', 3, NULL, 'PIECE', 'NEW', 0, 17, NULL),
  ('FRONT_PLEAT', 'Pregas frontais', 'Front pleats', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 18, NULL),
  ('USAGE_TYPE', 'Uso / esporte', 'Usage / sport', 'MULTI', 2, NULL, 'PIECE', 'NEW', 0, 19, 'Esporte nunca é variação nem subcategoria nova. As subcategorias legadas running_shoes, training_shoes, basketball_shoes e skate_shoes IMPLICAM o uso (RUNNING, TRAINING, BASKETBALL, SKATE).'),
  ('SHAFT_HEIGHT', 'Altura do cano', 'Shaft height', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 20, 'high_top_sneakers, ankle_boots e long_boots (legadas) IMPLICAM HIGH_TOP, ANKLE_HEIGHT e KNEE_HIGH respectivamente (valor padrão editável).'),
  ('HEEL_HEIGHT', 'Altura do salto', 'Heel height', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 21, NULL),
  ('HEEL_TYPE', 'Tipo de salto', 'Heel type', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 22, NULL),
  ('TOE_SHAPE', 'Bico', 'Toe shape', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 23, NULL),
  ('SOLE_TYPE', 'Solado', 'Sole', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 24, NULL),
  ('SIZE_CLASS', 'Tamanho (escala)', 'Size class', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 25, 'Escala visual do acessório (mini bag, óculos oversized, maxi argola). Não confundir com tamanho de vestuário (Taxonomy.SIZES).'),
  ('FRAME_RIM', 'Aro', 'Frame rim', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 26, NULL),
  ('LENS_TYPE', 'Lente', 'Lens', 'MULTI', 2, NULL, 'PIECE', 'NEW', 0, 27, NULL),
  ('CHAIN_LINK', 'Tipo de elo', 'Chain link', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 28, NULL),
  ('WATCH_DISPLAY', 'Mostrador', 'Display', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 29, NULL),
  ('WATCH_STRAP', 'Pulseira do relógio', 'Watch strap', 'SINGLE', 1, NULL, 'PIECE', 'NEW', 0, 30, NULL);

